hl.on("hyprland.start", function()
    hl.exec_cmd("yubikey-touch-detector --libnotify")
    hl.exec_cmd("herd start wayland-hyprland-env wayland-1 $HYPRLAND_INSTANCE_SIGNATURE")
    hl.exec_cmd("herd start darkman")
    hl.exec_cmd("~/.guix-home/profile/libexec/xdg-desktop-portal-gtk -r")
    hl.exec_cmd("~/.guix-home/profile/libexec/xdg-desktop-portal-hyprland")
    hl.exec_cmd("sleep 5; ~/.guix-home/profile/libexec/xdg-desktop-portal -r")
    hl.exec_cmd("waybar")
    hl.exec_cmd("swaync")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("gammastep-indicator")
    hl.exec_cmd("udiskie --tray")
    hl.exec_cmd("lxpolkit")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("syncthing-gtk")
    hl.exec_cmd("xsettingsd")
    hl.exec_cmd("gpg-connect-agent updatestartuptty /bye")
    hl.exec_cmd("hypridle")
end)

